        for r,c in cells:
            if 0<=r<H and 0<=c<W: out[r][c]=color
    for m in sing:
        mi=m[0]; mc=I[mi[0]][mi[1]]
        # nearest object(s) by min manhattan from marker to object cells
        order=sorted(objs,key=lambda o:min(manh(mi,q) for q in o))
        # try each nearest object; for each dihedral variant, find translations placing a copy cell ON marker; pick those where all other copy cells fall inside grid & don't overwrite non-bg cells
        cands=[]
        for o in order:
            onorm=norm(o); phis=dihedral(onorm)
            for phi in phis:
                T=(mi[0]-phi[0][0], mi[1]-phi[0][1])  # variant cell 0 at marker; alternative anchor cells
                # allow any anchor cell -> marker
                pass
        best=None
        for o in order:
            onorm=norm(o); phis=dihedral(onorm)
            for phi in phis:
                for pi in phi:
                    T=(mi[0]-pi[0], mi[1]-pi[1])
                    S=set((a+T[0],b+T[1]) for a,b in phi)
                    # constraint: within grid, no overwrites of non-marker/non-bg (except marker itself is fine since recolored anyway)
                    valid=True
                    for r,c in S:
                        if not(0<=r<H and 0<=c<W): valid=False;break
                        if (r,c)!=mi and I[r][c]!=bg: valid=False;break
                    if valid:
                        # prefer placements keeping copy "near" marker / minimal extent? collect
                        best_key=lambda c_: (-manh(mi,c_[0]), sum(max(0,r) for r,_ in c_), sum(max(0,c) for _,c in c_)) if False else None
                        cands.append((o,len(o),S,T,phi.index(pi)))
        # choose: smallest |S|? or anchor cell closest to marker? For ties try mode-specific scoring
        if mode=='minsize':
            cands.sort(key=lambda c: len(c[2]))
        elif mode=='minmax':
            cands.sort(key=lambda c: (-manh(mi,c[2].pop()) if False else None)[:0])
        else:
            cands.sort(key=lambda c:(-manh(mi,min(c[2]))) if False else None)
        if cands:
            o_,sz,S,T,idx=cands[0]
            draw(S,mc)
        else:
            # fallback: no anchor-on-marker; search any T where stamp==some subset pattern? skip
            pass
    return out

