def analyze(n):
    I=G[f'Demo pair {n} input']; O=G[f'Demo pair {n} output']
    bg=Counter(sum(I,[])).most_common(1)[0][0]
    cs=comps(I,bg); objs=sorted([p for p in cs if len(p)>1]); sing=[p for p in cs if len(p)==1]
    info=[]
    for m in sing:
        mi=m[0]; mc=I[mi]
        # all object variants
        variants=[(o,v) for o in objs for v in dihedral(norm(o))]
        # exact cover: stamp cells == set(v+T) for some T, marker either in stamp or orthogonally adjacent, copy on far side of object->marker line
        cands=[]
        for o,v in variants:
            Vs={p for p in v}
            # translations placing a copy cell on/on-marker or adjacent: collect T where stamp subset ok
            # constraint: stamp cells within grid, no non-bg/non-marker overwrite
            badT=set()
            # efficient: for each copy cell q in v, T=q-mi gives marker-inside; T=q-(mi+dr) gives adjacency
            baseT=set(q-mi for q in v) | set(q-mi-d for q in v for dr in ((0,1),(0,-1),(1,0),(-1,0)))
            validTs=[]
            for T in baseT:
                S={(a+T[0],b+T[1]) for a,b in v}
                if all(0<=r<len(O) and 0<=c<len(O[0]) for r,c in S) and all((r,c)!=mi and (O[r][c]==mc or I[r][c]==bg) for r,c in S):
                    # side check: object cell nearest marker vs copy cell nearest marker on opposite sides
                    nd_o=min(manh(mi,q) for q in o)
                    nc_q=min(manh(mi,q) for q in S if q!=mi)
                    sideok = True
                    # simple: copy cell nearest marker must not be between marker and object
                    qn=min(S,key=lambda q:(manh(mi,q),q))
                    qo=min(o,key=lambda q:(manh(mi,q),q))
                    # vector signs differ in at least one coordinate => opposite sides
                    vq=(qn[0]-mi[0],qn[1]-mi[1]); vo=(qo[0]-mi[0],qo[1]-mi[1])
                    if vq[0]*vo[0]>=0 and vq[1]*vo[1]>=0: sideok=False
                    validTs.append((T,S,len(S),sideok))
            cands.extend(validTs)
        info.append((m,mc,[(T,S,sz,side) for T,S,sz,side in cands][:6]))
    return info
