g=[[4,4,4,4,4,4,4,4,4,4,4],[4,4,4,4,4,4,4,3,7,4,4],[4,4,4,4,4,2,4,2,1,4,4],[4,4,4,4,4,4,2,4,4,4,4],[4,4,4,1,4,4,4,4,4,4,4],[4,8,8,6,4,4,4,4,8,4,4],[4,4,8,4,4,4,4,4,4,2,2],[4,4,4,4,4,4,4,4,4,4,4],[4,4,4,4,4,4,4,4,4,4,4],[4,4,4,4,7,4,4,4,4,4,4],[4,4,4,4,7,4,4,4,4,4,4],[4,4,4,5,7,7,4,4,4,4,4],[4,4,4,0,4,4,4,4,4,4,5],[4,4,4,4,4,4,4,4,4,7,5],[4,4,4,4,4,4,4,4,4,9,4],[4,4,4,4,4,4,4,4,4,4,4]]
H,W=len(g),len(g[0]); seen=set()
def comps():
    for i in range(H):
        for j in range(W):
            if g[i][j]!=4 and (i,j) not in seen:
                st=[(i,j)]; c=set(); col=g[i][j]
                while st:
                    x,y=st.pop()
                    if (x,y) in c: continue
                    c.add((x,y)); seen.add((x,y))
                    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                        nx,ny=x+dx,y+dy
                        if 0<=nx<H and 0<=ny<W and g[nx][ny]!=4 and (nx,ny) not in seen:
                            st.append((nx,ny))
                yield col,sorted(c)
out=[r[:] for r in g]
for col,c in comps():
    if len(c)<2: continue
    cnt=collections.Counter(g[p[0]][p[1]] for p in c)
    maj=cnt.most_common(1)[0][0]
    for x,y in c: out[x][y]=maj if g[x][y]==maj else 4
print(json.dumps(out))
